class Solution:
    def combine(self, nums: list[int], target: int) -> list[list[int]]:
        dp = []
        res = []
        def backtrack(i, total):
            if total == target:
                if dp in res:
                    return
                res.append(dp.copy())
                return
            if i == len(nums):
                return
            if total + nums[i] <= target:
                total += nums[i]
                dp.append(nums[i])
                backtrack(i, total)
                tomin = dp.pop()
                total -= tomin
            backtrack(i+1, total)
        backtrack(0,0)
        return res

