class Solution:
    def while_it_has_neighbors(self, grid, row, col, ROW, COL, is_visited):
        if (row < 0 or col < 0 or row == ROW or col == COL):
            return
        if (grid[row][col] == '0' or is_visited[row][col]):
            is_visited[row][col] = True
            return
