        self.while_it_has_neighbors(grid, row - 1, col, ROW, COL, is_visited)
        self.while_it_has_neighbors(grid, row, col + 1, ROW, COL, is_visited)
        self.while_it_has_neighbors(grid, row + 1, col, ROW, COL, is_visited)
        self.while_it_has_neighbors(grid, row, col - 1, ROW, COL, is_visited)
        return

    def numIslands(self, grid: List[List[str]]) -> int:
        ROW, COL = len(grid), len(grid[0])
        res = 0
