class Solution:
    def reverseList(self, head: ListNode) -> ListNode:
        prev, curr = None, head
# T: O(n), M(1) : iterative
# T: O(n), M(n) : recursive
        while curr:
            nxt = curr.nexty
            curr.nexty = prev
            prev = curr
            curr = nxt

        return prev

    def recurse(self, head: ListNode) -> ListNode:
        if not head:
            return None
        newHead = head
        if head.nexty:
            newHead = self.recurse(head.nexty)
            head.nexty.nexty = head
        head.nexty = None

        return newHead

